CREATE DATABASE IF NOT EXISTS library_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE library_management;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS fines; DROP TABLE IF EXISTS book_transactions; DROP TABLE IF EXISTS librarians; DROP TABLE IF EXISTS students; DROP TABLE IF EXISTS books; DROP TABLE IF EXISTS categories; DROP TABLE IF EXISTS system_settings; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (user_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','librarian','student') NOT NULL, full_name VARCHAR(140) NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE students (student_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,student_number VARCHAR(50) NOT NULL UNIQUE,department VARCHAR(100) NOT NULL DEFAULT '',status ENUM('active','inactive') NOT NULL DEFAULT 'active',CONSTRAINT fk_students_user FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE librarians (librarian_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,employee_number VARCHAR(50) NOT NULL UNIQUE,CONSTRAINT fk_librarians_user FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE categories (category_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE books (book_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,isbn VARCHAR(30) NOT NULL UNIQUE,title VARCHAR(220) NOT NULL,author VARCHAR(160) NOT NULL,publisher VARCHAR(160) NOT NULL DEFAULT '',total_copies INT UNSIGNED NOT NULL DEFAULT 0,available_copies INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('active','archived') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_books_category FOREIGN KEY(category_id) REFERENCES categories(category_id) ON DELETE SET NULL,CHECK(available_copies<=total_copies)) ENGINE=InnoDB;
CREATE TABLE book_transactions (transaction_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,librarian_id BIGINT UNSIGNED NOT NULL,returned_by BIGINT UNSIGNED NULL,issue_date DATE NOT NULL,due_date DATE NOT NULL,return_date DATE NULL,status ENUM('issued','returned') NOT NULL DEFAULT 'issued',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_loan_status_due(status,due_date),INDEX idx_loan_student(student_id,status),CONSTRAINT fk_tx_book FOREIGN KEY(book_id) REFERENCES books(book_id),CONSTRAINT fk_tx_student FOREIGN KEY(student_id) REFERENCES students(student_id),CONSTRAINT fk_tx_librarian FOREIGN KEY(librarian_id) REFERENCES users(user_id),CONSTRAINT fk_tx_returned_by FOREIGN KEY(returned_by) REFERENCES users(user_id)) ENGINE=InnoDB;
CREATE TABLE fines (fine_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,payment_status ENUM('unpaid','paid') NOT NULL DEFAULT 'unpaid',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fine_tx FOREIGN KEY(transaction_id) REFERENCES book_transactions(transaction_id),CHECK(amount>=0)) ENGINE=InnoDB;
CREATE TABLE system_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
